class MainSearch {
  MainSearch({
      List<Edges> edges,}){
    _edges = edges;
}

  MainSearch.fromJson(dynamic json) {
    if (json['edges'] != null) {
      _edges = [];
      json['edges'].forEach((v) {
        _edges.add(Edges.fromJson(v));
      });
    }
  }
  List<Edges> _edges;
MainSearch copyWith({  List<Edges> edges,
